// === Tab: mySketch ===

var pythonCode = `

import random
import math

fr = 120
max_fr = 120
looping = True
hide_info = False
collision = False
speed_limit = False
record = False

def setup():
    global objects
    size(800, 600, FX2D)
    # fullScreen(FX2D)
    frameRate(fr)
    pixelDensity(displayDensity());
    nb_objects = 1
    objects = []
    for i in range(nb_objects):
        objects.append(Glower(objects))


def draw():
    global fr
    background(0)
    noStroke()

    for o in objects:
        if collision:
            o.collide()
        if looping:
            o.update()
        o.plot()

    if mousePressed:
        for o in objects:
            o.attraction = False

    if not hide_info:
        textSize(30)
        alfa = 100
        # Object count
        fill(255, 255, 255, alfa)
        text("count: "+str(len(objects)), 20, 40)

        # FPS
        if frameCount%60 == 1:
            fr = frameRate
        if fr >= 30:
            fill(0, 255, 0, alfa)
        else:
            fill(255, 0, 0, alfa)
        text("fps: "+str(int(fr)), 20, 80)

        # Collision
        if not collision:
            fill(255, 0, 0, alfa)
        else:
            fill(0, 255, 0, alfa)
        text("collision: "+str(collision), 160, 40)

        # Speed
        if speed_limit:
            fill(255, 0, 0, alfa)
        else:
            fill(0, 255, 0, alfa)
        text("speed: "+("Slowed" if speed_limit else "Max"), 160, 80)


    noStroke()
    fill(255)
    if mousePressed:
        fill(255, 0, 0)
    ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 8, 8)

    if record:
        saveFrame("frames/particles-######.png")
        fill(255, 0, 0)
        ellipse(width-20, 20, 20, 20)

def mouseReleased():
    for o in objects:
        o.attraction = True    


def keyPressed():
    global objects, looping, hide_info, max_fr, collision, speed_limit, record
    if key == ' ':
        objects.append(Glower(objects, collision))
    elif key == ('R' or 'r'):
        objects = []
    elif key == ('F' or 'f'):
        looping = not looping
    elif key == ('H' or 'h'):
        hide_info = not hide_info
    elif key == ('S' or 's'):
        speed_limit = not speed_limit
        if max_fr == 30:
            max_fr = 120
        else:
            max_fr = 30
        frameRate(max_fr)
    elif key == ('C' or 'c'):
        collision = not collision
        for object in objects:
            object.collision = not object.collision
    elif key == '\n':
        record = not record

class Glower():
    def __init__(self, others, col=False):
        self.location = PVector(width/2, height/2)
        self.velocity = PVector(0, 0)
        self.acceleration = PVector(0, 0)
        self.velocity_limit = random.uniform(7, 10)
        self.mouse_mag = random.uniform(0.3, 1) 
        self.attraction = True
        self.collision = col
        self.others = others
        self.spring = 0.1

        self.radius = 50
        self.c1 = color(255, 255, 255)
        self.c2 = color(random.randint(0, 255), random.randint(0, 255), random.randint(0, 255))

    def collide(self):
        for other in self.others:
            if (other.location.x - self.location.x)**2 + (other.location.y - self.location.y)**2 <= (self.radius-20)**2:
                dx = other.location.x - self.location.x
                dy = other.location.y - self.location.y
                angle = math.atan2(dy, dx)
                touching_dist = other.radius + self.radius
                targetX = self.location.x + math.cos(angle)*touching_dist
                targetY = self.location.y + math.sin(angle)*touching_dist

                av = PVector(targetX, targetY)
                av.sub(self.location)
                av.mult(self.spring)
                self.velocity.sub(av)
                av = PVector(targetX, targetY)
                av.sub(other.location)
                av.mult(other.spring)
                other.velocity.add(av)

    def update(self):
        if self.attraction:
            mouse = PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
            mouse.sub(self.location)
            mouse.setMag(self.mouse_mag)
            self.acceleration = mouse

        self.velocity.add(self.acceleration)
        self.location.add(self.velocity)
        self.velocity.limit(self.velocity_limit)

    def plot(self):
        # Fading and gradient colored:
        # for r in range(self.radius, 0, -1):
            # h = map(r, 0, self.radius, 0, 0.3)
            # c = lerpColor(self.c1, self.c2, h)
            # a = int(map(r, self.radius, 0, 0, 255/10))
            # fill(c, a)
            # ellipse(self.location.x, self.location.y, r, r)
        stroke(255)
        fill(self.c2, 80)
        if self.collision:
            fill(self.c2)
        ellipse(self.location.x, self.location.y, self.radius-20, self.radius-20)

`;

function setup() {
	runPyCode(pythonCode);
	remove();//remove the JS version
}

